<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Domain\Marketing\MarketingPermission as P;
use App\Services\Marketing\MarketingContentTemplates as Templates;
use App\Services\Marketing\Email\{TemplateService,TemplateStarterPreviewService,SmsMessageService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Storage};
use Illuminate\Validation\ValidationException;
use App\Models\MarketingContentTemplate;
class MarketingEmailSmsController extends Controller {
 private function actor(Request $r,bool $edit=false):int {abort_unless(P::allows($r->user(),$edit?P::EDIT:P::VIEW),403);return $r->user()->id;}
 private function starters():array {return json_decode(file_get_contents(resource_path('marketing-email-starters.json')),true,512,JSON_THROW_ON_ERROR);}
 private function template(Request $r,?string $id,string $channel){if(!$id)return null;$t=app(Templates::class)->query($this->actor($r))->findOrFail($id);abort_unless($t->channel===$channel,404);return $t;}
 public function catalog(Request $r){$this->actor($r);$service=new TemplateStarterPreviewService(new TemplateService());$catalogTemplates=$this->starters();$categoryCounts=[];foreach($catalogTemplates as &$t){$t['preview_html']=$service->render($t['document']);$categoryCounts[$t['category']]=($categoryCounts[$t['category']]??0)+1;}unset($t);ksort($categoryCounts);return response()->view('marketing.templates.email-catalog',compact('catalogTemplates','categoryCounts')+['catalogConfiguration'=>'{"batchSize":6}'])->header('Cache-Control','private, no-store');}
 public function editor(Request $r,?string $id=null){$this->actor($r,true);$t=$this->template($r,$id,'email');abort_if($t?->archived_at,409,'Restore this template before editing.');$selectedStarterTemplate=null;foreach($this->starters() as $starter)if((string)$starter['starter_template_id']===(string)$r->query('starter'))$selectedStarterTemplate=$starter;
  abort_if($r->filled('starter')&&!$selectedStarterTemplate,404);$doc=$t?->document??[];$service=new TemplateService();$form=['name'=>$t?->name??'','status'=>strtolower($t?->state??'Draft'),'subject'=>$doc['subject']??$selectedStarterTemplate['subject']??'','preheader'=>$doc['preheader']??$selectedStarterTemplate['preheader']??'','editor_json'=>$service->createInitialEditorJson(isset($doc['editor_document'])?json_encode($doc['editor_document']):($selectedStarterTemplate['editor_json']??''),$doc['content_html']??$doc['body']??''),'content_html'=>$service->sanitizeHtml($doc['content_html']??'')];
  foreach(['name'=>'template_name','status'=>'status','subject'=>'subject','preheader'=>'preheader','editor_json'=>'editor_json','content_html'=>'content_html'] as $key=>$field)if($r->session()->hasOldInput($field))$form[$key]=old($field);
  $editorStarterTemplates=$this->starters();$editorConfiguration=json_encode(['initialDocument'=>json_decode($form['editor_json'],true),'jsonFieldId'=>'template-editor-json','htmlFieldId'=>'template-content-html','mediaEndpoint'=>url('/admin/marketing/campaigns/templates/email/media'),'socialIconBaseUrl'=>asset('marketing-studio/crm-email/images/social'),'socialIconColorUrl'=>url('/marketing/email-social-icon'),'csrfToken'=>csrf_token(),'starterTemplates'=>array_map(fn($x)=>['id'=>$x['starter_template_id'],'name'=>$x['name'],'subject'=>$x['subject'],'preheader'=>$x['preheader'],'document'=>$x['document']],$editorStarterTemplates)],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);
  return response()->view('marketing.templates.email-editor',compact('form','selectedStarterTemplate','editorStarterTemplates','editorConfiguration')+['pageTitle'=>$t?'Edit Email Template':'Create Email Template','isEditMode'=>(bool)$t,'formAction'=>url('/admin/marketing/campaigns/templates/email/save'.($t?'/'.$t->id:'')),'formErrors'=>session('errors')?session('errors')->all():[],'version'=>$t?->version??0])->header('Cache-Control','private, no-store');
 }
 public function sms(Request $r,?string $id=null){$this->actor($r,true);$t=$this->template($r,$id,'sms');abort_if($t?->archived_at,409,'Restore this template before editing.');$form=['name'=>$t?->name??'','status'=>strtolower($t?->state??'Draft'),'content_text'=>$t?->document['content_text']??$t?->document['body']??''];$analysis=(new SmsMessageService())->analyse($form['content_text']);return response()->view('marketing.templates.sms-editor',compact('form','analysis')+['isEditMode'=>(bool)$t,'formAction'=>url('/admin/marketing/campaigns/templates/sms/save'.($t?'/'.$t->id:'')),'formErrors'=>session('errors')?session('errors')->all():[],'version'=>$t?->version??0,'crmClientBrand'=>app(\App\Support\ShopBrand::class)->name()])->header('Cache-Control','private, no-store');}
 public function save(Request $r,string $channel,?string $id=null){$u=$this->actor($r,true);abort_unless(in_array($channel,['email','sms']),404);$input=$r->validate(['version'=>'required|integer|min:0','template_name'=>'required|string|max:150','status'=>'required|in:draft,active','subject'=>'nullable|string|max:255','preheader'=>'nullable|string|max:255','editor_json'=>'nullable|string|max:2000000','content_html'=>'nullable|string|max:500000','sms_message'=>'nullable|string|max:1000']);$t=app(\App\Services\Marketing\MarketingEmailSmsTemplates::class)->save($u,$channel,$input,$id);
  if($r->expectsJson())return response()->json(['template'=>app(Templates::class)->view($t)],$id?200:201);return redirect('/admin/marketing/campaigns/templates#edit/'.$t->id);
 }
 public function media(Request $r){$u=$this->actor($r,$r->isMethod('post'));if($r->isMethod('post')){$r->validate(['image'=>'required|image|mimes:jpeg,png,gif,webp|max:5120']);$file=$r->file('image');$path=$file->store('marketing/email/'.$u,'public');app(\App\Services\Marketing\MarketingMediaSources::class)->safeEmail($u,$path,$file->getClientOriginalName());$item=['url'=>Storage::disk('public')->url($path),'name'=>$file->getClientOriginalName(),'width'=>getimagesize($file->getRealPath())[0],'height'=>getimagesize($file->getRealPath())[1],'file_size'=>$file->getSize()];return response()->json(['success'=>true,'item'=>$item]);}
  $items=[];foreach(Storage::disk('public')->files('marketing/email/'.$u) as $path){if($r->filled('search')&&!str_contains(basename($path),$r->string('search')))continue;$size=@getimagesize(Storage::disk('public')->path($path));if(!$size)continue;$items[]=['url'=>Storage::disk('public')->url($path),'name'=>basename($path),'width'=>$size[0],'height'=>$size[1],'file_size'=>Storage::disk('public')->size($path)];}foreach(\App\Models\ProductImage::query()->join('products','products.id','=','product_images.product_id')->select('product_images.*','products.title as product_title')->when($r->filled('search'),fn($q)=>$q->where('products.title','like','%'.(string)$r->query('search').'%'))->orderBy('product_images.id')->limit(200)->get() as $image){$path=app(\App\Services\Marketing\MarketingPosts::class)->imagePath($image->path);if(!$path)continue;$root=str_replace('\\','/',Storage::disk('public')->path(''));$file=str_replace('\\','/',$path);$public=str_replace('\\','/',public_path()).'/';if(str_starts_with($file,$root))$url=Storage::disk('public')->url(substr($file,strlen($root)));elseif(str_starts_with($file,$public))$url=asset(substr($file,strlen($public)));else continue;$size=@getimagesize($path);if(!$size)continue;$items[]=['url'=>$url,'name'=>$image->product_title,'width'=>$size[0],'height'=>$size[1],'file_size'=>filesize($path)];}$page=max(1,(int)$r->query('page',1));return response()->json(['success'=>true,'items'=>array_slice($items,($page-1)*24,24),'pagination'=>['page'=>$page,'total_pages'=>max(1,(int)ceil(count($items)/24)),'total_rows'=>count($items)]])->header('Cache-Control','private, no-store');
 }
 public function icon(string $platform,string $color){abort_unless(in_array($platform,['facebook','instagram','tiktok','youtube','x','linkedin','pinterest','whatsapp','telegram'],true)&&preg_match('/^[0-9a-f]{6}$/i',$color),404);$file=public_path('marketing-studio/crm-email/images/social/dark/'.$platform.'-plain.png');abort_unless(is_file($file),404);$im=imagecreatefrompng($file);imagealphablending($im,false);for($x=0;$x<imagesx($im);$x++)for($y=0;$y<imagesy($im);$y++){$rgba=imagecolorat($im,$x,$y);$alpha=($rgba>>24)&127;$new=imagecolorallocatealpha($im,hexdec(substr($color,0,2)),hexdec(substr($color,2,2)),hexdec(substr($color,4,2)),$alpha);imagesetpixel($im,$x,$y,$new);}imagesavealpha($im,true);ob_start();imagepng($im);$png=ob_get_clean();imagedestroy($im);return response($png)->header('Content-Type','image/png')->header('Cache-Control','public, max-age=86400')->header('X-Content-Type-Options','nosniff');}
}
